+  aspect-ratio: 16/10;
+  position: relative;
+}
+.story-lead .story-visual { aspect-ratio: 4/5; }
+.story-visual-1 { background:
+  radial-gradient(500px 300px at 50% 50%, rgba(231,200,151,.18), transparent 60%),
+  linear-gradient(160deg, #2a2218 0%, #11100c 100%); }
+.story-visual-2 { background:
+  radial-gradient(260px 180px at 60% 40%, rgba(147,182,155,.18), transparent 60%),
+  linear-gradient(160deg, #1e2a22 0%, #0f1411 100%); }
+.story-visual-3 { background:
+  radial-gradient(260px 180px at 30% 60%, rgba(245,177,105,.18), transparent 60%),
+  linear-gradient(160deg, #2c2419 0%, #14110b 100%); }
+.story-visual-4 { background:
+  radial-gradient(260px 180px at 50% 30%, rgba(180,180,200,.12), transparent 60%),
+  linear-gradient(160deg, #232733 0%, #11131a 100%); }
+
+.story-link > h3, .story-link > p, .story-meta {
+  padding: 0 22px;
+}
+.story-meta {
+  margin-top: 18px;
+  display: flex; gap: 14px; align-items: center;
+  font-size: 12px; color: var(--text-mute);
