+.footer-brand .brand-name { font-size: 20px; color: var(--text); font-weight: 600; }
+.footer-brand p { margin: 6px 0 0; font-size: 14px; color: var(--text-mute); max-width: 32ch; }
+.site-footer nav {
+  display: grid;
+  grid-template-columns: repeat(3, 1fr);
+  gap: 32px;
+}
+.footer-col h3 {
+  font-size: 13px; letter-spacing: .14em; text-transform: uppercase;
+  color: var(--text); margin: 0 0 14px; font-weight: 600;
+}
+.footer-col ul { list-style: none; padding: 0; margin: 0; display: flex; flex-direction: column; gap: 10px; }
+.footer-col a { font-size: 14px; transition: color var(--t); }
+.footer-col a:hover { color: var(--accent); }
+
+.footer-bottom {
+  display: flex; justify-content: space-between; align-items: center;
+  padding-top: 24px; border-top: 1px solid var(--line);
+  font-size: 13px;
+}
+.legal { list-style: none; padding: 0; margin: 0; display: flex; gap: 18px; }
+.legal a { transition: color var(--t); }
+.legal a:hover { color: var(--accent); }
+
+/* RESPONSIVE */
+@media (max-width: 1080px) {
+  .product-grid { grid-template-columns: repeat(3, 1fr); }
+  .editorial-grid { grid-template-columns: 1fr 1fr; }
+  .story-lead { grid-row: span 1; grid-column: span 2; }
+  .story-lead .story-visual { aspect-ratio: 16/8; }
+}
+
+@media (max-width: 860px) {
+  .primary-nav { display: none; }
+  .hero { padding: 40px 0 56px; }
+  .hero-inner { grid-template-columns: 1fr; gap: 32px; }
+  .hero-visual { height: 360px; }
