+  .hero-card-2 { width: 200px; }
+  .hero-card-3 { width: 190px; }
+  .swatch { height: 170px; }
+  .section { padding: 64px 0; }
+  .section-head { flex-direction: column; align-items: flex-start; }
+  .deals-grid { grid-template-columns: 1fr 1fr; }
+  .deal-feature { grid-column: span 2; grid-row: auto; }
+  .news-inner { grid-template-columns: 1fr; gap: 32px; }
