    { id: 'p8', name: 'Leather Weekender', cat: 'Accessories', price: 395, was: null, badge: null, visual: 'pv-8' }
  ];

  function fmt(n) { return '$' + n.toLocaleString('en-US'); }

  function renderProducts() {
    const grid = document.getElementById('product-grid');
    if (!grid) return;
    const html = products.map(p => {
      const badge = p.badge
        ? `<span class="product-badge ${p.badge === 'New' ? 'badge-new' : p.badge === 'Sale' ? 'badge-sale' : ''}">${p.badge}</span>`
        : '';
      const was = p.was ? `<span class="was"><span class="visually-hidden">Was </span>${fmt(p.was)}</span>` : '';
      return `
        <li class="product">
          <div class="product-visual ${p.visual}">
            ${badge}
            <button type="button" class="wishlist" aria-pressed="false" aria-label="Add ${p.name} to wishlist" data-id="${p.id}">
              <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M12 20s-7-4.5-9.3-9.1C1.2 7.6 3.4 4 7 4c2 0 3.5 1.1 5 3 1.5-1.9 3-3 5-3 3.6 0 5.8 3.6 4.3 6.9C19 15.5 12 20 12 20z"/></svg>
            </button>
          </div>
          <p class="product-cat">${p.cat}</p>
          <h3 class="product-name"><a href="#" class="product-link">${p.name}</a></h3>
          <div class="product-foot">
            <p class="product-price">${fmt(p.price)} ${was}</p>
            <button type="button" class="add-btn" data-id="${p.id}" aria-label="Add ${p.name} to cart">Add</button>
          </div>
        </li>`;
    }).join('');
    grid.innerHTML = html;

    grid.addEventListener('click', onGridClick);
  }

  function onGridClick(e) {
    const add = e.target.closest('.add-btn');
    const wish = e.target.closest('.wishlist');
    if (add) {
      const original = add.textContent;
      add.classList.add('added');
      add.textContent = 'Added ✓';
      const cartBtn = document.querySelector('.cart-btn');
      const counter = cartBtn ? cartBtn.querySelector('.cart-count') : null;
      if (counter) {
        const n = (parseInt(counter.textContent, 10) || 0) + 1;
        counter.textContent = String(n);
        cartBtn.setAttribute('aria-label', `Cart, ${n} item${n === 1 ? '' : 's'}`);
      }
      setTimeout(() => {
        add.classList.remove('added');
        add.textContent = original;
      }, 1500);
    }
    if (wish) {
      const pressed = wish.getAttribute('aria-pressed') === 'true';
      wish.setAttribute('aria-pressed', String(!pressed));
    }
  }

  // Countdown — ends at next midnight (local)
  function startCountdown() {
    const el = document.getElementById('countdown');
    if (!el) return;
    const end = new Date();
    end.setHours(23, 59, 59, 999);
    function pad(n) { return String(n).padStart(2, '0'); }
    function tick() {
      const diff = end - new Date();
      if (diff <= 0) { el.textContent = '00:00:00'; return; }
      const h = Math.floor(diff / 3600000);
      const m = Math.floor((diff % 3600000) / 60000);
      const s = Math.floor((diff % 60000) / 1000);
      el.textContent = `${pad(h)}:${pad(m)}:${pad(s)}`;
    }
    tick();
    setInterval(tick, 1000);
  }

  // Newsletter
  function setupNewsletter() {
    const form = document.getElementById('newsletter-form');
    if (!form) return;
    const input = form.querySelector('input[type="email"]');
    const status = form.querySelector('.news-status');

    form.addEventListener('submit', function (e) {
      e.preventDefault();
      const value = (input.value || '').trim();
      const valid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
      if (!valid) {
        input.setAttribute('aria-invalid', 'true');
        status.textContent = 'Please enter a valid email address.';
        status.className = 'news-status err';
        input.focus();
        return;
      }
      input.removeAttribute('aria-invalid');
      status.textContent = `Thank you. Look out for a confirmation in your inbox.`;
      status.className = 'news-status ok';
      input.value = '';
    });

    input.addEventListener('input', function () {
      if (input.getAttribute('aria-invalid') === 'true') {
        input.removeAttribute('aria-invalid');
        status.textContent = '';
        status.className = 'news-status';
      }
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    renderProducts();
    startCountdown();
    setupNewsletter();
  });
})();
